
/* DJ-02 19n: override scoped to DJ-02 only. No changes to DJ-01 / DL-01. */
const dj02Image='data:image/png;base64,';
const dj02Coords={
 Apellido:[96,258,221,24],Nombre:[91,317,225,24],Dni:[89,373,224,24],Sexo:[65,413,110,24],
 Domicilio:[142,450,208,23],Localidad:[135,481,215,23],Titulo:[183,508,170,23],
 Otorgado:[156,538,196,23],Registro:[156,568,64,23],Clase:[281,568,71,23],
 Antiguedad:[153,596,199,23],Presentada:[186,627,166,23]
};
const dj02ColX=[445,524,726,886,948,1004,1099,1262];
const dj02Y=[305,328,352,376,400,422,449,475,502,527,556,584,610,635,661];
function dj02ProfileValues(){
 const map={Apellido:document.getElementById('perfilApellidos')?.value||'',Nombre:document.getElementById('perfilNombres')?.value||'',Dni:document.getElementById('dni')?.value||'',Sexo:document.getElementById('sexo')?.value||'',Domicilio:document.getElementById('perfilDomicilio')?.value||'',Localidad:document.getElementById('perfilLocalidad')?.value||'',Titulo:document.getElementById('perfilTitulo')?.value||'',Otorgado:document.getElementById('perfilOtorgado')?.value||'',Registro:document.getElementById('perfilRegistro')?.value||'',Clase:document.getElementById('perfilClase')?.value||'',Antiguedad:document.getElementById('perfilAntiguedadVista')?.value||''};
 return map;
}
function dj02SyncProfile(){const p=dj02ProfileValues();for(const [k,v] of Object.entries(p))dj02Set(k,v);dj02MissingNotice()}
function dj02MissingNotice(){
 const names={Apellido:'Apellido',Nombre:'Nombre',Dni:'DNI',Sexo:'Sexo',Domicilio:'Domicilio',Localidad:'Localidad',Titulo:'Título',Otorgado:'Otorgado por',Registro:'N.º de registro',Clase:'Clase',Antiguedad:'Antigüedad'};
 const missing=Object.keys(names).filter(k=>!dj02Val(k).trim());const el=document.getElementById('dj02Missing');
 const editor=document.querySelector('.dj02-edit');
 editor.hidden=!missing.length&&!editor.open;
 if(el)el.innerHTML=missing.length?'<strong>Faltan datos para completar el DJ-02:</strong> '+missing.map(k=>names[k]).join(' · ')+'. <button type="button" class="alt" onclick="document.querySelector(\'.dj02-edit\').open=true">Completar ahora</button>':'';
}
function dj02Open(){
 if(!dj02Loaded){dj02Loaded=true;try{const d=JSON.parse(localStorage.getItem('adc_dj02_v1')||'null');dj02Records=Array.isArray(d?.rows)?d.rows:[];if(d?.fields?.Presentada){$('dj02Presentada').add(new Option(d.fields.Presentada,d.fields.Presentada));dj02Set('Presentada',d.fields.Presentada)}}catch(e){dj02Records=[]}}
 dj02SyncProfile();dj02Render();
}
function dj02Date(s){if(!s)return '';const m=String(s).match(/^(\d{4})-(\d{2})-(\d{2})$/);return m?m[3]+'/'+m[2]+'/'+m[1]:s}
function dj02Rect(x,y,w,h,content,klass){
 return '<div class="dj02-overlay '+klass+'" style="left:'+(x/1311*100)+'%;top:'+(y/796*100)+'%;width:'+(w/1311*100)+'%;height:'+(h/796*100)+'%" title="'+esc(content||'')+'">'+esc(content||'')+'</div>';
}
function dj02Preview(){
 const el=document.getElementById('dj02Preview');if(!el)return;
 dj02MissingNotice();let overlays='';
 for(const [key,box] of Object.entries(dj02Coords)){const raw=dj02Val(key);const value=['Dni','Registro','Clase'].includes(key)?adcPersonalFormat(raw,key==='Clase'?'perfilClase':key):raw;if(value)overlays+=dj02Rect(...box,value,'dj02-person')}
 const keys=['articulo','inciso','motivo','desde','hasta','disposicion','unidad'];
 for(let i=0;i<14;i++)keys.forEach((k,j)=>{const r=dj02Records[i]||{};const x=dj02ColX[j]+2,w=dj02ColX[j+1]-dj02ColX[j]-4;let v=r[k]||'';if(k==='desde'||k==='hasta')v=dj02Date(v);if(v)overlays+=dj02Rect(x,dj02Y[i]+2,w,dj02Y[i+1]-dj02Y[i]-4,v,'dj02-row')});
 el.innerHTML='<div class="dj02-paper"><img alt="Plantilla original DJ-02, sin recuadros" src="'+dj02Image+'">'+overlays+'</div>';
 const warn=document.getElementById('dj02Overflow');if(warn)warn.textContent=dj02Records.length>14?'Hay '+dj02Records.length+' antecedentes. Esta hoja admite 14 renglones; los adicionales todavía no se imprimen. No imprimas hasta resolver la continuación.':'';
}
const dj02OriginalRender=dj02Render;
dj02Render=function(){dj02OriginalRender();dj02Preview()};
// All personal fields automatically refresh when the source profile changes.
for(const id of ['nombre','dni','sexo','perfilDomicilio','perfilLocalidad','perfilTitulo','perfilOtorgado','perfilRegistro','perfilClase','perfilAntiguedadVista']){
 const input=document.getElementById(id);if(input)input.addEventListener('input',()=>{if(!document.getElementById('dj02').classList.contains('hide')){dj02SyncProfile();dj02Preview()}})
}
for(const k of dj02Fields){const el=document.getElementById('dj02'+k);if(el)el.addEventListener('input',()=>dj02Preview())}
